	sky_material.ground_horizon_color = HAZE
	sky_material.ground_bottom_color = HAZE
	sky_material.ground_curve = 0.05
	sky_material.sun_angle_max = 25.0
	sky_material.sun_curve = 0.12

	var sky := Sky.new()
